def classify_existing_pools(apps, schema_editor):
    """
    Classify legacy QuestionPools based on their existing contents:
    - Only MCQ items -> MCQ
    - Only Coding items -> CODING
    - Empty -> None (requires explicit admin classification)
    - Mixed (both MCQ & Coding) -> None (preserves all items for manual reconciliation)
    """
    QuestionPool = apps.get_model('assessments', 'QuestionPool')
    QuestionPoolItem = apps.get_model('assessments', 'QuestionPoolItem')
    ProgrammingQuestion = apps.get_model('assessments', 'ProgrammingQuestion')

    coding_q_ids = set(ProgrammingQuestion.objects.values_list('question_id', flat=True))

    for pool in QuestionPool.objects.all():
        items = list(
            QuestionPoolItem.objects.filter(pool_id=pool.id).select_related('question')
        )
        if not items:
            pool.question_type = None
            pool.save(update_fields=['question_type'])
            continue

        has_mcq = False
        has_coding = False
        for item in items:
            q = item.question
            is_coding = (
                q.id in coding_q_ids
                or (getattr(q, 'assessment_type', '') or '').strip().upper() == 'CODING'
                or (getattr(q, 'section_type', '') or '').strip().upper() == 'CODING'
            )
            if is_coding:
                has_coding = True
            else:
                has_mcq = True

        if has_mcq and not has_coding:
            pool.question_type = 'MCQ'
        elif has_coding and not has_mcq:
            pool.question_type = 'CODING'
        else:
            # Mixed pool: preserve all records untouched and require manual reconciliation
            pool.question_type = None
        pool.save(update_fields=['question_type'])


